package util

import (
	"fmt"

	"github.com/easysoft/gitfox-community/pkg/git/enum"
)

func GetHookTemplates() (hookNames, hookTpls, giteaHookTpls []string) {
	hookNames = []string{"pre-receive", "update", "post-receive"}
	hookTpls = []string{
		// for pre-receive
		fmt.Sprintf(`#!/usr/bin/env %s
# AUTO GENERATED BY GITFOX, DO NOT MODIFY
data=$(cat)
exitcodes=""
hookname=$(basename $0)
GIT_DIR=${GIT_DIR:-$(dirname $0)/..}

for hook in ${GIT_DIR}/hooks/${hookname}.d/*; do
  test -x "${hook}" && test -f "${hook}" || continue
  echo "${data}" | "${hook}"
  exitcodes="${exitcodes} $?"
done

for i in ${exitcodes}; do
  [ ${i} -eq 0 ] || exit ${i}
done
`, enum.ScriptType),

		// for update
		fmt.Sprintf(`#!/usr/bin/env %s
# AUTO GENERATED BY GITFOX, DO NOT MODIFY
exitcodes=""
hookname=$(basename $0)
GIT_DIR=${GIT_DIR:-$(dirname $0/..)}

for hook in ${GIT_DIR}/hooks/${hookname}.d/*; do
	test -x "${hook}" && test -f "${hook}" || continue
	"${hook}" $1 $2 $3
	exitcodes="${exitcodes} $?"
done

for i in ${exitcodes}; do
	[ ${i} -eq 0 ] || exit ${i}
done
`, enum.ScriptType),

		// for post-receive
		fmt.Sprintf(`#!/usr/bin/env %s
# AUTO GENERATED BY GITFOX, DO NOT MODIFY
data=$(cat)
exitcodes=""
hookname=$(basename $0)
GIT_DIR=${GIT_DIR:-$(dirname $0)/..}

for hook in ${GIT_DIR}/hooks/${hookname}.d/*; do
  test -x "${hook}" && test -f "${hook}" || continue
  echo "${data}" | "${hook}"
  exitcodes="${exitcodes} $?"
done

for i in ${exitcodes}; do
  [ ${i} -eq 0 ] || exit ${i}
done
`, enum.ScriptType),
	}

	giteaHookTpls = []string{
		// for pre-receive
		fmt.Sprintf(`#!/usr/bin/env %s
# AUTO GENERATED BY GITFOX, DO NOT MODIFY
"%s" hooks pre-receive
`, enum.ScriptType, loadGitfoxBinPath()),

		// for update
		fmt.Sprintf(`#!/usr/bin/env %s
# AUTO GENERATED BY GITFOX, DO NOT MODIFY
refname="$1"
oldrev="$2"
newrev="$3"

get_mail() {
	mail=""
	author_email=$(git log -1 --pretty=format:'%%ae' $newrev)
	author_email=$(echo "$author_email" | tr '[:upper:]' '[:lower:]')
	email_username=$(echo "$author_email" | cut -d '@' -f 1)
	mail=$(echo "$email_username" | tr -d '.')
	echo "$mail"
}

zero=$(git hash-object --stdin </dev/null | tr '[0-9a-f]' '0')
if [ "$newrev" = "$zero" ]; then
	newrev_type=delete
else
	newrev_type=$(git cat-file -t $newrev)
fi

case "$refname","$newrev_type" in
%s	*)
		exit 0
	;;
esac
exit 0
`, enum.ScriptType, pushRequestHookCase),

		// for post-receive
		fmt.Sprintf(`#!/usr/bin/env %s
# AUTO GENERATED BY GITEA, DO NOT MODIFY
"%s" hooks post-receive
`, enum.ScriptType, loadGitfoxBinPath()),
	}
	return hookNames, hookTpls, giteaHookTpls
}
